from collections import deque

def valid_path(n, edges, source, destination):
    if source == destination:
        return True
    adj = {i: [] for i in range(n)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    visited = {source}
    q = deque([source])
    while q:
        curr = q.popleft()
        if curr == destination:
            return True
        for nxt in adj[curr]:
            if nxt not in visited:
                visited.add(nxt)
                q.append(nxt)
    return False

